import { Logger } from '@nestjs/common';
import { ApiHideProperty, OmitType } from '@nestjs/swagger';
import { IsNotEmpty, IsOptional, IsString, IsUUID } from 'class-validator';
import { BasicResponseDTO } from '../../basicResponseDTO';
