                recordValue: runningTimeTotal,
                serviceId: groupedVms[key][0].paigoServiceId,
                applicationId: groupedVms[key][0].paigoApplicationId,
                _measurement: UsageEntity._measurement,
            });
            res.push(entity);
            StandardMeasurementEntity.publish(entity);
        });
        return res;
    }
