import { Test, TestingModule } from '@nestjs/testing';
import { ConflictException, NotFoundException } from '@nestjs/common';
import { CustomerService } from './customer.service';
import { InfluxService } from '../influx/influx.service';
import { OfferingService } from '../offering/offering.service';
import { UsageService } from '../usage/usage.service';
import { SchedulerService } from '../scheduler/scheduler.service';
import { CustomerEntity } from './entities/customer.entity';
import { paymentChannel } from './dto/create-customer.dto';

describe('CustomerService', () => {
    const businessID = 'myCoolCorp';
    const customerId = 'e345f409-daca-4144-91d2-0a0f87c96581';
    const offeringId = 'abcd1234-asf2-4444-aaaa-kashaskjh3421';
    const customerDbModel = {
        _measurement: CustomerEntity._measurement,
        _value: 'myCoolCustomer',
        _time: new Date().toISOString(),
        businessID,
        customerId,
        offeringId,
        paymentChannel: paymentChannel.Stripe,
        email: 'founders@paigo.tech',
    };
    const offering = { offeringId, offeringName: 'myCoolOffering', dimensions: [{ dimensionId: '12345' }] };

    let service: CustomerService;
    const mockGetLatestCustomer = jest.fn(() => [customerDbModel]);
    const mockGetLatestCustomers = jest.fn(() => [customerDbModel]);
    const mockGetAllCustomersWithOfferingId = jest.fn(() => [customerDbModel]);
    const mockGetInvoicesForCustomer = jest.fn(() => []);
    const mockLoadPoints = jest.fn();
    const mockOfferingFindOne = jest.fn(() => ({ data: [offering], message: 'Found Offering' }));
    const mockFindUsageForCustomer = jest.fn(() => [{ dimensionId: '12345', usage: [] }]);
    const mockSchedulerRemove = jest.fn();

    beforeEach(async () => {
        process.env.STAGE = 'unit-test';
        const module: TestingModule = await Test.createTestingModule({
            providers: [CustomerService],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => ({ tag: jest.fn(), stringField: jest.fn() }),
                        getLatestCustomer: mockGetLatestCustomer,
                        getLatestCustomers: mockGetLatestCustomers,
                        getAllCustomersWithOfferingId: mockGetAllCustomersWithOfferingId,
                        getInvoicesForCustomer: mockGetInvoicesForCustomer,
                    };
                }
                if (token === OfferingService) {
                    return { findOne: mockOfferingFindOne };
                }
                if (token === UsageService) {
                    return { findUsageForCustomer: mockFindUsageForCustomer };
                }
                if (token === SchedulerService) {
                    return { remove: mockSchedulerRemove, create: jest.fn() };
                }
            })
            .compile();

        service = module.get<CustomerService>(CustomerService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    it('returns the offeringId and the hydrated offering when reading a customer', async () => {
        const {
            data: [customer],
        } = await service.findOne({ customerId, businessID });
        expect(mockOfferingFindOne).toBeCalledWith({ businessID, offeringId });
        expect(customer.offeringId).toEqual(offeringId);
        expect(customer.offering).toEqual(offering);
        expect(customer.invoices).toEqual([]);
    });

    it('returns the hydrated offering when listing customers', async () => {
        const { data } = await service.findAll({ businessID });
        expect(data[0].offeringId).toEqual(offeringId);
        expect(data[0].offering).toEqual(offering);
    });

    it('reads a customer without an offering', async () => {
        mockGetLatestCustomer.mockImplementationOnce(() => [{ ...customerDbModel, offeringId: undefined }]);
        const {
            data: [customer],
        } = await service.findOne({ customerId, businessID });
        expect(mockOfferingFindOne).not.toBeCalled();
        expect(customer.offering).toBeUndefined();
    });

    it('throws when the customer does not exist', async () => {
        mockGetLatestCustomer.mockImplementationOnce(() => []);
        await expect(service.findOne({ customerId, businessID })).rejects.toThrow(NotFoundException);
    });

    it('wraps the usage found for a customer', async () => {
        const query = { startTime: '2023-01-01T00:00:00Z' };
        const response = await service.findUsageForCustomer({ businessID, customerId }, query);
        expect(mockFindUsageForCustomer).toBeCalledWith({ customerId, businessID }, query);
        expect(response).toEqual({ data: [{ dimensionId: '12345', usage: [] }], message: 'Found usage' });
    });

    it('finds every customer attached to an offering', async () => {
        const { data } = await service.findAllCustomersWithOfferingId({ businessID, offeringId });
        expect(mockGetAllCustomersWithOfferingId).toBeCalledWith({ businessID, offeringId });
        expect(data[0].customerId).toEqual(customerId);
    });

    it('deletes a customer even when legacy service records exist', async () => {
        const response = await service.remove({ customerId, businessID });
        expect(response).toEqual({ message: 'Deleted Customer', customerId });
        expect(mockLoadPoints).toBeCalledTimes(1);
    });

    it('does not delete a customer which does not exist', async () => {
        mockGetLatestCustomer.mockImplementationOnce(() => []);
        await expect(service.remove({ customerId, businessID })).rejects.toThrow(NotFoundException);
        expect(mockLoadPoints).not.toBeCalled();
    });

    it('propagates conflicts raised while gathering usage', async () => {
        mockFindUsageForCustomer.mockImplementationOnce(() => {
            throw new ConflictException('no offering');
        });
        await expect(service.findUsageForCustomer({ businessID, customerId }, {})).rejects.toThrow(ConflictException);
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { ConflictException } from '@nestjs/common';
import { CustomerService } from '../customer/customer.service';
import { InfluxService } from '../influx/influx.service';
import { aggregationInterval } from '../dimensions/dto/create-dimension.dto';
import { UsageService } from './usage.service';
import { StandardMeasurementEntity } from '../measurement-config/entities/standardMeasurement.entity';
import { UsageEntity } from './entities/usage.entity';

describe('UsageService', () => {
    const businessID = 'myCoolCorp';
    const customerId = 'e345f409-daca-4144-91d2-0a0f87c96581';
    const offeringId = 'abcd1234-asf2-4444-aaaa-kashaskjh3421';
    const dimensions = [
        { dimensionId: '12345', aggregationInterval: aggregationInterval.hour },
        { dimensionId: '67890', aggregationInterval: aggregationInterval.hour },
    ];
    const offering = { offeringId, offeringName: 'myCoolOffering', dimensions };

    let service: UsageService;
    const mockGetAggregateUsageForDimension = jest.fn(() => [{ dimensionId: '12345', usage: [] }]);
    const mockCustomerFindOne = jest.fn(() => ({
        data: [{ customerId, offeringId, offering }],
        message: 'Found Customer',
    }));

    beforeEach(async () => {
        process.env.STAGE = 'unit-test';
        const module: TestingModule = await Test.createTestingModule({
            providers: [UsageService],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        getAggregateUsageForDimension: mockGetAggregateUsageForDimension,
                        getPoint: () => ({ tag: jest.fn(), floatField: jest.fn(), timestamp: jest.fn() }),
                    };
                }
                if (token === CustomerService) {
                    return { findOne: mockCustomerFindOne };
                }
            })
            .compile();

        service = module.get<UsageService>(UsageService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    it('aggregates the usage of the customer offering dimensions with the customerId', async () => {
        const startTime = '2023-01-01T00:00:00Z';
        const endTime = '2023-01-02T00:00:00Z';
        const response = await service.findUsageForCustomer({ customerId, businessID }, { startTime, endTime });
        expect(mockCustomerFindOne).toBeCalledWith({ customerId, businessID });
        expect(mockGetAggregateUsageForDimension).toBeCalledWith(
            expect.objectContaining({
                customerId,
                clientID: customerId,
                businessID,
                startTime,
                endTime,
                offeringDocument: { offeringId, offeringName: 'myCoolOffering', dimensions },
            })
        );
        expect(response).toEqual([{ dimensionId: '12345', usage: [] }]);
    });

    it('overrides the aggregation interval of every dimension of the offering', async () => {
        await service.findUsageForCustomer(
            { customerId, businessID },
            { aggregationInterval: aggregationInterval.day }
        );
        const [[{ offeringDocument }]] = mockGetAggregateUsageForDimension.mock.calls as any;
        expect(offeringDocument.dimensions).toEqual([
            { dimensionId: '12345', aggregationInterval: aggregationInterval.day },
            { dimensionId: '67890', aggregationInterval: aggregationInterval.day },
        ]);
    });

    it('defaults the queried time range to the last day', async () => {
        await service.findUsageForCustomer({ customerId, businessID }, {});
        const [[{ startTime, endTime }]] = mockGetAggregateUsageForDimension.mock.calls as any;
        expect(new Date(endTime).getTime() - new Date(startTime).getTime()).toEqual(864e5);
    });

