import { MeasurementFormat } from './measurement.interface';
import { StandardMeasurementEntity } from './standardMeasurement.entity';
import {
    PreProcessorMeasurementType,
    StandardMeasurementPreProcessorEntity,
} from './standardMeasurementPreProcessor';
import { InfluxService } from '../../influx/influx.service';
import { UsageEntity } from '../../usage/entities/usage.entity';

describe('StandardMeasurement', () => {
    const businessID = 'myCoolCorp';
    const customerId = 'e345f409-daca-4144-91d2-0a0f87c96581';
    const dimensionId = 'da9611bd-e0f3-4c0d-a754-fda5be730872';

    afterEach(() => {
        jest.restoreAllMocks();
    });

    it('persists the customerId as an influx tag', () => {
        const mockTag = jest.fn();
        const influxService = {
            getPoint: () => ({ tag: mockTag, floatField: jest.fn(), timestamp: jest.fn() }),
        } as unknown as InfluxService;
        const entity = new StandardMeasurementEntity({
            businessID,
            customerId,
            dimensionId,
            recordValue: 0.87,
            metadata: {},
            _measurement: UsageEntity._measurement,
        });

        MeasurementFormat.getPointForm(entity, influxService);

        expect(mockTag).toBeCalledWith('customerId', customerId);
        expect(mockTag).toBeCalledWith('dimensionId', dimensionId);
        expect(mockTag).toBeCalledWith('businessID', businessID);
    });

    it('restores the customerId from the datastore model', () => {
        const measurement = MeasurementFormat.toEntity({
            _time: '2023-02-08T19:24:10Z',
            _measurement: UsageEntity._measurement,
            _field: 'recordValue',
            _value: 0.87,
            businessID,
            customerId,
            dimensionId,
            metadata_environment: 'staging',
        } as never);

        expect(measurement.customerId).toEqual(customerId);
        expect(measurement.metadata).toEqual({ environment: 'staging' });
    });

    it('allows the paigo customer and dimension tags to be gathered from infrastructure', () => {
        const tags = StandardMeasurementEntity.awsTagKeyReducer([
            { Key: 'paigoCustomerId', Value: customerId },
            { Key: 'paigoDimensionId', Value: dimensionId },
            { Key: 'someOtherTag', Value: 'ignored' },
        ]);

        expect(tags).toEqual({ paigoCustomerId: customerId, paigoDimensionId: dimensionId });
    });

    it('maps the kubernetes customer and dimension labels onto the measurement', async () => {
        const publishMock = jest.spyOn(StandardMeasurementEntity, 'publish').mockImplementation(() => undefined);
        const influxService = {
            getLatestPodLabelsByID: jest.fn(() => [
                {
                    label_paigo_customer_id: customerId,
                    label_paigo_dimension_id: dimensionId,
                },
            ]),
        } as unknown as InfluxService;
        const preProcessed = new StandardMeasurementPreProcessorEntity(
            '0.05',
            businessID,
            PreProcessorMeasurementType.AGENT,
            { pod: 'myCoolPod' },
            '2023-02-08T19:24:10Z'
        );

        await StandardMeasurementPreProcessorEntity.createStandardMeasurement(
            preProcessed,
            'myCoolPod',
            influxService
        );

        expect(publishMock).toBeCalledWith(
            expect.objectContaining({
                businessID,
                customerId,
                dimensionId,
                recordValue: 0.05,
                _measurement: UsageEntity._measurement,
            })
        );
    });

    it('returns early when a pod has no paigo labels', async () => {
        const publishMock = jest.spyOn(StandardMeasurementEntity, 'publish').mockImplementation(() => undefined);
        const influxService = {
            getLatestPodLabelsByID: jest.fn(() => []),
        } as unknown as InfluxService;
        const preProcessed = new StandardMeasurementPreProcessorEntity(
            '0.05',
            businessID,
            PreProcessorMeasurementType.AGENT,
            { pod: 'myCoolPod' }
        );

        const response = await StandardMeasurementPreProcessorEntity.createStandardMeasurement(
            preProcessed,
            'myCoolPod',
            influxService
        );

        expect(response).toEqual({ message: 'No labels found' });
        expect(publishMock).not.toBeCalled();
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { aggregationInterval, aggregationMethod } from '../dimensions/dto/create-dimension.dto';
import { InfluxService } from './influx.service';

describe('InfluxService', () => {
    let service: InfluxService;
    const collectRows = jest.fn(() => []);

    beforeEach(async () => {
        process.env.STAGE = 'unit-test';
        const module: TestingModule = await Test.createTestingModule({
            providers: [InfluxService],
        }).compile();

        service = module.get<InfluxService>(InfluxService);
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        jest.spyOn(service.dbclient, 'getQueryApi').mockImplementation(() => ({ collectRows }));
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    it('filters aggregated usage by the customerId', async () => {
        await service.aggregateDimensionUsageQuery({
            businessID: 'myCoolCorp',
            dimensionId: '12345',
            aggregationInterval: aggregationInterval.hour,
            aggregationMethod: aggregationMethod.sum,
            startDate: new Date('2023-01-01T00:00:00Z'),
            endDate: new Date('2023-01-02T00:00:00Z'),
            customerId: 'e345f409-daca-4144-91d2-0a0f87c96581',
        });
        const [[query]] = collectRows.mock.calls as unknown as string[][];
        expect(query).toContain('r["customerId"] == "e345f409-daca-4144-91d2-0a0f87c96581"');
        expect(query).not.toContain('r["serviceId"]');
    });

    it('filters unaggregated usage by the customerId', async () => {
        await service.dimensionUsageNoAggregation({
            businessID: 'myCoolCorp',
            dimensionId: '12345',
            startDate: new Date('2023-01-01T00:00:00Z'),
            endDate: new Date('2023-01-02T00:00:00Z'),
            customerId: 'e345f409-daca-4144-91d2-0a0f87c96581',
        });
        const [[query]] = collectRows.mock.calls as unknown as string[][];
        expect(query).toContain('r["customerId"] == "e345f409-daca-4144-91d2-0a0f87c96581"');
        expect(query).not.toContain('r["serviceId"]');
    });

    it('falls back to the legacy service filters when no customer is given', async () => {
        await service.dimensionUsageNoAggregation({
            businessID: 'myCoolCorp',
            dimensionId: '12345',
            startDate: new Date('2023-01-01T00:00:00Z'),
            endDate: new Date('2023-01-02T00:00:00Z'),
            serviceId: 'legacy-service',
        });
        const [[query]] = collectRows.mock.calls as unknown as string[][];
        expect(query).toContain('r["serviceId"] == "legacy-service"');
    });

    it('finds the customers attached to an offering', async () => {
        await service.getAllCustomersWithOfferingId({
            businessID: 'myCoolCorp',
            offeringId: 'abcd1234-asf2-4444-aaaa-kashaskjh3421',
        });
        const [[query]] = collectRows.mock.calls as unknown as string[][];
        expect(query).toContain('r["offeringId"] == "abcd1234-asf2-4444-aaaa-kashaskjh3421"');
        expect(query).toContain('r["_measurement"] == "CustomerConfig"');
    });
});

