    const customerId = 'e345f409-daca-4144-91d2-0a0f87c96581';
    const offeringId = 'abcd1234-asf2-4444-aaaa-kashaskjh3421';

    it('persists the offeringId of a customer', () => {
        const mockTag = jest.fn();
        const influxService = {
            getPoint: () => ({ tag: mockTag, stringField: jest.fn() }),
        } as unknown as InfluxService;
        const entity = new CustomerEntity({
            customerId,
            offeringId,
            businessID: 'myCoolCorp',
            customerName: 'myCoolCustomer',
            paymentChannel: paymentChannel.Stripe,
            taxExempt: TaxExempt.none,
