        expect(mockTag).toBeCalledWith('offeringId', offeringId);
        expect(mockTag).toBeCalledWith('customerId', customerId);
    });

    it('restores the offeringId of a customer', () => {
        const entity = CustomerEntity.dbModelToEntity({
            _value: 'myCoolCustomer',
            customerId,
            offeringId,
            paymentChannel: paymentChannel.Stripe,
