import { PrivateAPIServicesModule } from '../src/services/services.module';
import { PrivateAPICustomerModule } from '../src/customer/customer.module';
import { ServicesService } from '../src/services/services.service';
import { CustomerService } from '../src/customer/customer.service';
import { PublicAPICustomerController } from '../src/customer/customer.controller';

jest.setTimeout(60000);
describe('inherited module metadata', () => {
    it('private modules inherit providers and exports', async () => {
        const moduleRef = await Test.createTestingModule({
            imports: [PrivateAPIServicesModule, PrivateAPICustomerModule],
        }).compile();
        const servicesService = moduleRef.get(ServicesService, { strict: false });
        expect(servicesService).toBeDefined();
        expect(servicesService.customerService).toBeDefined();
        const customerService = moduleRef.get(CustomerService, { strict: false });
        expect(customerService.usageService).toBeDefined();
        const controller = moduleRef.get(PublicAPICustomerController, { strict: false });
        expect(controller).toBeDefined();
        await moduleRef.close();
    });
});
EOF
npx jest --config ./jest.unit.config.json --rootDir . --testRegex "tmptest/wiring2.spec.ts$" --runInBand --forceExit 2>&1 | tail -20; rm -rf tmptest

